async function resolveBacktestSymbol(){
  const symbol=$('#backtest-symbol').value.trim(),c=config();if(!symbol)return;
  if(!/^[0-9]{6}$/.test(symbol))throw Error('请输入六位股票代码。');
  const covers=r=>r?.from<=c.from&&r?.to>=c.to;
  if(activeBundle?.metadata?.symbol===symbol&&covers(activeBundle.metadata.requested))return;
  if(!backtestSnapshots.size)await refreshBacktestSnapshots();
  const matches=[...backtestSnapshots.values()].filter(x=>x.symbol===symbol&&covers(x.report?.requested)).sort((a,b)=>b.syncedAt.localeCompare(a.syncedAt));
  if(!matches.length)throw Error(`${symbol} 没有覆盖 ${c.from} — ${c.to} 的本地行情快照。点击“采集此代码与区间”，先完成采集；已有行情不足时需补充对应区间和预热历史。`);
  const id=matches[0].id;await loadBundle(await api('/api/data/bundle?id='+id),'按代码与日期选取的行情',false,id);
  setConfig({...c,board:activeBundle.metadata.board,dataMode:bundleMode(activeBundle)});updateSource();renderQuality();
}
