function renderTPairs(){const rows=result.tPairs;return '<div class="optimizer-intro"><h3>T 配对审计</h3><p>超时或止损会亏损；未配对不计作盈利。股息和送转按实际登记库存进入整段波段盈亏。</p></div><div class="table-wrap"><table><thead><tr><th>方向</th><th>开 T</th><th>结束</th><th>股数</th><th>净价差 / 元</th><th>状态 / 原因</th></tr></thead><tbody>'+ (rows.length?rows.slice(-30).reverse().map(t=>`<tr><td>${t.direction==='positive'?'正 T':'反 T'}</td><td>${t.start}</td><td>${t.end}</td><td>${num(t.quantity,0)}</td><td class="${cls(t.pnl)}">${num(t.pnl)}</td><td>${t.status==='paired'?'已配对':'未配对'} · ${esc(t.reason)}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">本方案没有 T 配对。需要 5 / 15 分钟、有效日线趋势、可卖旧仓与足够的费后价差。</td></tr>')+'</tbody></table></div>';}
$('#compare-management').onclick=async()=>{const b=$('#compare-management'),c=config(),runData=activeBundle??data;b.disabled=true;b.textContent='正在对照训练 / 验证…';try{if(source==='import'&&!activeBundle&&c.dataMode!=='exploration')throw Error('正式方案研究需要完整数据包。');const comparison=await compute('management',runData,c);const rows=comparison.rows;$('#management-results').innerHTML=`<div class="validation-split">训练 ${comparison.trainFrom} — ${comparison.trainTo}<br>验证 ${comparison.validationFrom} — ${comparison.validationTo} · 每种方案独立从空仓开始<br>训练准入 ${comparison.qualified} 种${comparison.qualified===0?' · 样本 / 质量不足，不推荐方案':''}</div><div class="table-wrap"><table><thead><tr><th>仓位方案</th><th>训练收益 / 平仓数</th><th>验证收益</th><th>验证相对底仓</th><th>验证回撤</th><th>验证 T 已配 / 未配</th><th>操作</th></tr></thead><tbody>${rows.map((r,i)=>r.error?`<tr><td>${r.name}</td><td colspan="6">${esc(r.error)}</td></tr>`:`<tr><td>${r.name}<br>${r.quality.reason}</td><td class="${cls(r.training.total)}">${pct(r.training.total,true)} / ${r.training.closedTrades}</td><td class="${cls(r.validation.total)}">${pct(r.validation.total,true)}</td><td class="${cls(r.validationDelta)}">${pct(r.validationDelta,true)}</td><td>${pct(r.validation.maxdd)}</td><td>${r.validation.tPaired} / ${r.validation.tUnmatched}</td><td><button class="load-params" data-management="${i}">回测验证段</button></td></tr>`).join('')}</tbody></table></div><p class="stats-note" style="padding-top:16px">排序只使用训练段交易质量。所有方案使用相同初始底仓上限与风险预算；加仓会改变敞口，净值差异包含仓位差异。T 净价差不能直接视为增益；验证收益及回撤才反映整个组合。合成演示不能证明实盘盈利，反复看验证结果调参后应保留新的验证样本。</p>`;$$('[data-management]').forEach(btn=>btn.onclick=()=>{setConfig({...rows[Number(btn.dataset.management)].config,from:comparison.validationFrom,to:comparison.validationTo});toast('已载入仓位方案及验证区间，点击运行回测。');});}catch(e){toast(e.message);}finally{b.disabled=false;b.textContent='运行 5 种仓位方案';}};

function updateFeePreview(){const c=config(),amount=1000000;try{const f=orderFees(amount,false,c,c.from).total+orderFees(amount,true,c,c.from).total;$('#fee-preview').textContent=`按当前费率（${c.taxMode==='historical'?c.from+'历史口径':'固定口径'}），同价各买卖100万元合计 ¥${num(f)}（不含滑点）。`;}catch{$('#fee-preview').textContent='请输入有效费率。';}}

const researchStage={queued:'排队',preflight:'环境检查',collect:'采集',validate:'校验',ingest:'入库',backtest:'后台回测',verify:'复现核对',report:'保存报告',completed:'完成',recovery:'恢复检查'};
const researchState={queued:'等待执行',running:'运行中',paused:'已暂停',blocked:'受阻',failed:'核对失败',completed:'已完成'};
function duration(ms){if(!Number.isFinite(ms))return '未记录';const s=Math.floor(Math.max(0,ms)/1000);return `${Math.floor(s/3600)}时${Math.floor(s%3600/60)}分${s%60}秒`;}
const queryNames={calendar:'交易日历',basic:'证券资料',daily:'独立日线',factors:'复权因子',dividends:'公司行动',hs300:'历史沪深300名单',minute:'5分钟K线'};
function researchTiming(j){
  const t=j.timing;if(!t)return '<p>旧任务尚无耗时记录，升级后开始累计。</p>';
  const current=t.runs?.at(-1);
  return `<p class="task-timing">累计运行 ${duration(t.activeMs)} · 本次运行 ${duration(current?.activeMs??0)} · ${esc(researchStage[j.stage]||j.stage)}阶段累计 ${duration(t.stages?.[j.stage]??0)}${j.status==='running'?' · 每5秒保存计时':''}</p>${t.legacyUnmeasured?'<p>升级前耗时未记录；当前累计从升级后的执行开始。</p>':''}${t.interruptedTailUnmeasured?'<p>曾意外中断：保留最后落盘时间，未落盘的末尾片段无法补测。</p>':''}`;
}
function researchTimingDetails(j){
  if(!j.timing)return '';
  const t=j.timing,reason={completed:'完成',paused:'暂停',blocked:'受阻',failed:'失败',interrupted:'意外中断'};
  return `<p>阶段耗时：${Object.entries(t.stages??{}).map(([k,v])=>`${esc(researchStage[k]||k)} ${duration(v)}`).join(' · ')||'尚未执行'}</p><ul>${(t.runs??[]).map((r,i)=>`<li>第${i+1}次 · ${esc(new Date(r.startedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}))} — ${r.endedAt?esc(new Date(r.endedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})):'运行中'} · ${duration(r.activeMs)} · ${esc(reason[r.stopReason]||'执行中')}</li>`).join('')}</ul>${Object.keys(j.queryTiming??{}).length?`<div class="table-wrap"><table><thead><tr><th>查询类型</th><th>完成 / 中断 / 缓存</th><th>累计耗时</th><th>其中限流等待</th><th>SDK请求数</th></tr></thead><tbody>${Object.entries(j.queryTiming).map(([k,v])=>`<tr><td>${esc(queryNames[k]||k)}</td><td>${v.completed} / ${v.failed} / ${v.cached}</td><td>${duration(v.elapsedMs)}</td><td>${duration(v.rateWaitMs)}</td><td>${v.requests}</td></tr>`).join('')}</tbody></table></div>`:''}<p>累计包括网络与限流等待，不包括暂停、排队或停机。查询耗时包含缓存读回校验；SDK请求数包含分页。被强制终止的在途请求未收到完成回执时，只计入阶段耗时。</p>`;
}
function researchJob(j,expandedJobs){
  const collectOnly=j.request?.purpose==='collect',progress=j.progress,query=progress?.query;
  const previousReport=j.reportHash&&(j.reportRun!==undefined?j.reportRun<(j.timing?.runs?.length??0):['running','queued'].includes(j.status));
  return `<article class="research-job"><h3>${esc(j.request?.symbol||j.id)} · ${esc(researchState[j.status]||j.status)} · ${esc(researchStage[j.stage]||j.stage)}</h3><p>${collectOnly?'仅采集行情 · 未校验沪深300成员':'沪深300正式研究'} · ${esc(j.request?.from||'')} — ${esc(j.request?.to||'')} · ${collectOnly?'原生5分钟':esc(j.request?.config?.timeframe||'')+'执行'} · ${j.request?.warmupSessions||0}日预热${j.acceptance==='synthetic-test-only'?' · 合成流程测试，非真实数据验收':''}</p>${j.collectionRange?`<p>实际采集范围（含预热）：${esc(j.collectionRange.from)} — ${esc(j.collectionRange.to)}</p>`:''}${researchTiming(j)}${query?`<p>本轮已核验 ${progress.checkpoints||0} 项查询（含断点复用）${progress.phase==='query-start'?' · 正在查询':progress.phase==='query-error'?' · 查询中断':' · 最近完成'} ${esc(query.join(' / '))}${progress.rows!==undefined?' · '+progress.rows+' 行':''}${progress.queryElapsedMs!==undefined?' · 本项耗时 '+duration(progress.queryElapsedMs):''}${progress.cached?' · 复用断点':''}</p>`:''}${j.quality?`<p>完整 ${j.quality.completeSessions} 日 · 已确认停牌 ${j.quality.suspendedSessions} 日 · ${j.quality.actual?.bars||0} 根 · ${j.quality.issues?.length||0} 类资料问题</p>`:''}${j.error?`<p class="research-error">${esc(j.error.code)}：${esc(j.error.message)}</p>`:''}${j.metrics?`<p>收益 ${pct(j.metrics.total,true)} · 最大回撤 ${pct(j.metrics.maxdd)} · 完整平仓 ${j.metrics.closedTrades} 段 · 总费用 ¥${num(j.metrics.fees)}${j.metrics.quantity?' · 期末仍有持仓':''}</p>`:''}${j.snapshotId?`<p>快照 <code>${esc(j.snapshotId)}</code></p>`:''}${j.reportHash?`<p>${previousReport?'上次尝试报告（本轮尚未完成）':'报告'} <code>${esc(j.reportHash)}</code></p>`:''}<div class="warehouse-actions">${['running','queued'].includes(j.status)?`<button class="text-button" data-task-action="pause" data-task="${j.id}">暂停</button>`:''}${['paused','blocked','failed'].includes(j.status)?`<button class="text-button" data-task-action="resume" data-task="${j.id}">断点恢复</button>`:''}${j.status==='completed'?`<button class="text-button" data-task-action="repeat" data-task="${j.id}">${collectOnly?'固定快照校验':'固定快照复现'}</button>`:''}${j.reportHash?`<a class="text-button" href="/api/research/jobs/${j.id}/report" download>${previousReport?'下载上次报告':'下载完整报告'}</a>`:''}<a class="text-button" href="/api/research/jobs/${j.id}/timing" download>下载耗时日志</a>${j.snapshotId?`<a class="text-button" href="/api/data/bundle?id=${esc(j.snapshotId)}" download="${esc(j.request?.symbol||'行情')}-snapshot.json">下载行情</a><button class="text-button" data-task-snapshot="${j.snapshotId}">查看行情</button><button class="load-params" data-task-backtest="${j.id}">载入并回测</button>${collectOnly?'':`<button class="text-button" data-task-optimize="${j.id}">载入并优化</button>`}`:''}</div><details data-task-logs="${esc(j.id)}"${expandedJobs.has(j.id)?' open':''}><summary>日志与资料问题</summary>${researchTimingDetails(j)}<ol>${(j.events||[]).slice(-20).map(e=>`<li>${esc(new Date(e.at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}))}${e.activeMs!==undefined?' · 累计 '+duration(e.activeMs)+' · 阶段 '+duration(e.stageMs):''} · ${esc(e.message)}</li>`).join('')}${(j.quality?.issues||[]).map(e=>`<li>${esc(e.code)} · ${esc(e.message)}（${e.count}） · ${esc((e.samples||[]).join('、'))}</li>`).join('')}</ol><p>页面显示最近日志；完整记录请下载耗时日志。</p></details></article>`;
}
let researchTimer=null,researchPage=0,pendingBatchSubmit=null;
function researchBatch(b){const c=b.counts,active=c.running||c.queued,attention=c.blocked+c.failed;return `<article class="research-batch"><h3>批量采集 · ${b.total} 只股票${b.paused?' · 已暂停':''}</h3><p>${esc(b.from||'')} — ${esc(b.to||'')} · ${b.purpose==='collect'?'仅采集行情':'沪深300正式研究'}</p><p>完成 ${c.completed} / ${b.total} · 运行 ${c.running} · 排队 ${c.queued} · 暂停 ${c.paused} · 受阻 / 失败 ${attention}${b.incomplete?' · '+b.incomplete+'只资料需检查':''}<br>累计执行 ${duration(b.activeMs)}${b.duplicates?' · 已去重 '+b.duplicates+' 个重复代码':''}</p>${b.error?`<p class="research-error">${esc(b.error.message)}</p>`:''}<p class="batch-symbols">${esc(b.symbols.join('、'))}</p><div class="warehouse-actions"><button type="button" class="text-button" data-batch-show="${b.id}">查看本批任务</button>${active?`<button type="button" class="text-button" data-batch-action="pause" data-batch="${b.id}">暂停整批</button>`:''}${b.paused||c.paused||attention?`<button type="button" class="text-button" data-batch-action="resume" data-batch="${b.id}">恢复未完成</button>`:''}</div></article>`;}
function renderResearchBatches(batches){
  const filter=$('#research-job-filter'),selected=filter.value;filter.innerHTML='<option value="all">全部任务</option>'+batches.map(b=>`<option value="${b.id}">本批 ${b.total}只 · ${esc(new Date(b.createdAt).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit'}))} · ${b.id.slice(0,4)}</option>`).join('');filter.value=batches.some(b=>b.id===selected)?selected:'all';
  const visible=batches.slice(0,10),chosen=batches.find(b=>b.id===filter.value);if(chosen&&!visible.includes(chosen))visible.unshift(chosen);$('#research-batches').innerHTML=visible.map(researchBatch).join('');
  $$('[data-batch-show]').forEach(b=>b.onclick=()=>{filter.value=b.dataset.batchShow;researchPage=0;refreshResearch();});
  $$('[data-batch-action]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const v=await api('/api/research/batches/'+b.dataset.batch+'/'+b.dataset.batchAction,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(v.resumeErrors?.length)toast('部分任务未能恢复，请查看逐只错误。');await refreshResearch();}catch(e){toast(e.message);b.disabled=false;}});
}
$('#research-job-filter').onchange=()=>{researchPage=0;refreshResearch();};$('#research-jobs-prev').onclick=()=>{researchPage=Math.max(0,researchPage-1);refreshResearch();};$('#research-jobs-next').onclick=()=>{researchPage++;refreshResearch();};
async function refreshResearch(){
  clearTimeout(researchTimer);
  try{const r=await fetch('/api/research/jobs');if(r.status===404){$('#research-status').textContent='此入口需要本地部署版后台。托管网站只支持手动导入；请启动本地部署包。';$('#research-submit').disabled=true;return;}const v=await r.json();if(!r.ok)throw Error(v.error||'任务后台不可用');
    $('#research-submit').disabled=false;$('#research-status').textContent='后台串行执行 · '+v.jobs.length+' 个持久任务 · 暂停和中断均保留已完成分段';
    // Capture after fetching: users may toggle a task's logs during the request.
    const jobsRoot=$('#research-jobs'),expandedJobs=new Set([...jobsRoot.querySelectorAll('details[open]')].map(d=>d.dataset.taskLogs));
    const focusedLogs=document.activeElement?.closest('details[data-task-logs]')?.dataset.taskLogs;
    renderResearchBatches(v.batches??[]);
    const selected=$('#research-job-filter').value,filtered=selected==='all'?v.jobs:v.jobs.filter(j=>j.batchId===selected),pages=Math.max(1,Math.ceil(filtered.length/20));researchPage=Math.min(researchPage,pages-1);$('#research-jobs-page').textContent=`第 ${researchPage+1} / ${pages} 页 · ${filtered.length} 项`;$('#research-jobs-prev').disabled=researchPage===0;$('#research-jobs-next').disabled=researchPage>=pages-1;
    $('#research-jobs').innerHTML=filtered.slice(researchPage*20,(researchPage+1)*20).map(j=>researchJob(j,expandedJobs)).join('');
    if(focusedLogs)[...jobsRoot.querySelectorAll('details[data-task-logs]')].find(d=>d.dataset.taskLogs===focusedLogs)?.querySelector('summary')?.focus({preventScroll:true});
    $$('[data-task-action]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/api/research/jobs/'+b.dataset.task+'/'+b.dataset.taskAction,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});await refreshResearch();}catch(e){toast(e.message);b.disabled=false;}});
    $$('[data-task-backtest]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const job=v.jobs.find(j=>j.id===b.dataset.taskBacktest);await backtestSnapshot(job.snapshotId,job.request);}catch(e){toast(e.message);}finally{b.disabled=false;}});
    $$('[data-task-snapshot]').forEach(b=>b.onclick=async()=>{try{await loadBundle(await api('/api/data/bundle?id='+b.dataset.taskSnapshot),'后台任务',false,b.dataset.taskSnapshot);toast('已载入任务快照；完整后台结果请下载报告。');}catch(e){toast(e.message);}});
    $$('[data-task-optimize]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const job=v.jobs.find(j=>j.id===b.dataset.taskOptimize);await loadBundle(await api('/api/data/bundle?id='+job.snapshotId),'后台任务',false,job.snapshotId);setConfig(job.request.config);showView('optimization');toast('已载入任务快照和原始研究区间，资金费用保持该任务配置。');}catch(e){toast(e.message);}finally{b.disabled=false;}});
    if(v.jobs.some(j=>['queued','running'].includes(j.status)))researchTimer=setTimeout(refreshResearch,3000);
  }catch(e){$('#research-status').textContent=e.message;}
}
function updateResearchRange(){
  const mode=$('#research-range').value,start=$('#research-start'),end=$('#research-end');
  const yesterday=new Date(Date.now()+8*3600000-86400000).toISOString().slice(0,10);
  start.readOnly=mode==='year';start.max=end.value||yesterday;end.max=yesterday;
  if(mode==='year'&&end.value){const d=new Date(end.value+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+1);d.setUTCFullYear(d.getUTCFullYear()-1);start.value=d.toISOString().slice(0,10);}
  start.setCustomValidity(start.value&&end.value&&start.value>=end.value?'研究开始日期必须早于结束日期':'');
  $('#research-start-note').textContent=mode==='year'?'（自动）':'';
  $('#research-range-help').textContent=mode==='year'?'从结束日回溯完整一年；开始日期自动计算。':'可选择几个月或跨多年；实际可用范围以供应商数据和完整性校验为准。';
}
['#research-range','#research-start','#research-end'].forEach(id=>$(id).addEventListener('input',updateResearchRange));
updateResearchRange();
function updateResearchPurpose(){const collectOnly=$('#research-purpose').value==='collect';$('#research-submit').textContent=($('#research-input-mode').value==='batch'?'批量':'')+(collectOnly?'采集行情':'采集并验收');$('#research-purpose-help').textContent=collectOnly?'仅下载、校验并保存指定证券行情；跳过历史沪深300名单，不运行策略回测。仍采集日线、历史ST/停牌、因子和公司行动，用于完整性核验。':'采集行情并验证历史沪深300成员资格；资料通过后运行正式回测、独立复现和账务核对。';$('#research-period').disabled=collectOnly;}
$('#research-purpose').addEventListener('change',updateResearchPurpose);updateResearchPurpose();
function updateResearchInput(){const batch=$('#research-input-mode').value==='batch';$('#research-single-field').hidden=batch;$('#research-symbol').disabled=batch;$('#research-symbol').required=!batch;$('#research-symbols-field').hidden=!batch;$('#research-symbols').disabled=!batch;$('#research-symbols').required=batch;updateResearchPurpose();updateBatchCodes();}
function updateBatchCodes(){const field=$('#research-symbols');field.setCustomValidity('');try{const p=parseCollectionCodes(field.value);$('#research-symbols-help').textContent=`${p.symbols.length} 只股票${p.duplicates?' · 去重 '+p.duplicates+' 项':''} · 共用所选日期；串行采集，沿用日预算和限流。`;}catch(e){$('#research-symbols-help').textContent=field.value?e.message:'支持换行、逗号或空格分隔；每批最多300只，重复代码自动去重。';if(field.value)field.setCustomValidity(e.message);}}
$('#research-input-mode').onchange=updateResearchInput;$('#research-symbols').oninput=updateBatchCodes;updateResearchInput();
$('#research-form').onsubmit=async e=>{e.preventDefault();updateResearchRange();if(!e.currentTarget.reportValidity())return;const button=$('#research-submit');button.disabled=true;try{
  const batch=$('#research-input-mode').value==='batch',body={purpose:$('#research-purpose').value,rangeMode:$('#research-range').value,from:$('#research-start').value,to:$('#research-end').value,config:{...config(),timeframe:$('#research-purpose').value==='collect'?'5m':$('#research-period').value}};
  if(batch){body.symbols=$('#research-symbols').value;parseCollectionCodes(body.symbols);const signature=JSON.stringify(body);if(pendingBatchSubmit?.signature!==signature)pendingBatchSubmit={signature,requestId:crypto.randomUUID()};body.requestId=pendingBatchSubmit.requestId;}else body.symbol=$('#research-symbol').value;
  const submitted=await api(batch?'/api/research/batches':'/api/research/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(batch){pendingBatchSubmit=null;toast(`${submitted.total} 只股票已保存，后台按队列逐只采集${submitted.duplicates?'；重复代码已去重':''}。`);}else toast('任务已保存并提交后台。');await refreshResearch();
}catch(e){toast(e.message);}finally{button.disabled=false;}};
$('#research-refresh').onclick=()=>refreshResearch();refreshResearch();

async function refreshSources(){
  const button=$('#sources-refresh');button.disabled=true;
  try{const response=await fetch('/api/research/sources');if(response.status===404){$('#sources-status').textContent='此检查入口需要本地部署版后台。';return;}const data=await response.json();if(!response.ok||data.error)throw Error(data.error||'数据源配置不可用');
    const labels={'ready-unprobed':'已配置 · 连通性未探测',healthy:'日线探测通过',blocked:'网络许可受阻',unavailable:'需要依赖 / 密钥 / 本地采集器',unhealthy:'探测失败'},names={baostock:'BaoStock',akshare:'AkShare / 东财',mootdx:'mootdx / 通达信',lixinger:'理杏仁',sina:'新浪'},codes={OPTIONAL_DEPENDENCY_MISSING:'可选SDK未安装',CREDENTIAL_MISSING:'缺少 LIXINGER_API_KEY',NETWORK_TCP_NOT_GRANTED:'当前执行环境未授予TCP连接',HOSTED_TCP_UNSUPPORTED:'托管网站不支持TCP采集，请用本地版',PYTHON_LOCAL_ONLY:'Python适配器在本地运行',COLLECTOR_LOCAL_ONLY:'分钟采集器在本地运行'};
    $('#sources-status').textContent=data.backend==='hosted'?'网站配置检查 · 不消耗行情或付费请求 · 密钥仅供网站后端使用':'配置检查缓存60秒 · 不消耗行情或付费请求 · 密钥仅保存在采集主机环境变量';
    $('#lixinger-probe').hidden=!(data.backend==='hosted'&&data.lixinger?.configured);
    const p=data.lixinger?.lastProbe;$('#lixinger-status').textContent=p?`上次日线验证：${p.ok?'通过':'未通过（'+p.code+'）'} · ${new Date(p.checkedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})} · ${p.symbol} · ${p.bars} 根。不能据此通过年度分钟验收。`:'';
    $('#sources-table').innerHTML='<table><thead><tr><th>来源</th><th>配置状态</th><th>日线 / 5分钟 / 因子</th><th>历史辅助资料</th></tr></thead><tbody>'+data.sources.map(s=>`<tr><td>${esc(names[s.name]||s.name)}<br><small>${esc(s.transport.toUpperCase())}${s.requiresKey?' · 需密钥':''}</small></td><td>${esc(labels[s.health.state]||s.health.state)}${s.health.code?'<br><small>'+esc(codes[s.health.code]||s.health.code)+'</small>':''}</td><td>${['daily','minute5','adj_factor'].map(k=>s.capabilities.includes(k)?'支持':'—').join(' / ')}</td><td>${s.capabilities.includes('historical_st')?'逐日ST、日历、历史成员、公司行动':'不提供完整历史准入资料'}</td></tr>`).join('')+'</tbody></table>';
  }catch(e){$('#sources-status').textContent=e.message;}finally{button.disabled=false;}
}
$('#sources-refresh').onclick=()=>refreshSources();refreshSources();
$('#lixinger-probe').onclick=async()=>{const button=$('#lixinger-probe');button.disabled=true;try{const v=await api('/api/sources/lixinger/probe',{method:'POST'});await refreshSources();toast(v.ok?'理杏仁日线验证通过'+(v.cached?'（缓存）':''):'理杏仁验证未通过：'+v.code);}catch(e){toast(e.message);}finally{button.disabled=false;}};

// The extracted local bundle omits the downloadable archive to avoid nesting.
$('#local-package-download').hidden=['localhost','127.0.0.1'].includes(location.hostname);

refreshBacktestSnapshots();
